export const arrayAndAccumFrom = function<TOut, TAccum>(
		iter: Generator<TOut, TAccum, void>
		): [TOut[], TAccum] {

	let lItems: TOut[] = []
	let finalVal: (TAccum | undefined) = undef
	while(true) {
		const {value, done} = iter.next()
		if (done) {
			finalVal = value
			break
		}
		else {
			lItems.push(value)
		}
	}
	return [lItems, finalVal]
}

