// ASYNC - returns a Promise<[TOut[], TAccum]

export const asyncArrayAndAccumFrom = async function<TOut, TAccum>(
		iter: AsyncGenerator<TOut, TAccum, void>
		): Promise<[TOut[], TAccum]> {

	let lItems: TOut[] = []
	let finalVal: (TAccum | undefined) = undef
	while(true) {
		const {value, done} = await iter.next()
		if (done) {
			finalVal = value
			break
		}
		else {
			lItems.push(value)
		}
	}
	return new Promise((resolve, reject) => {
		try {
			resolve([lItems, finalVal])
		}
		catch (err) {
			reject(err)
		}
	})
}

