export const valuesFrom = async function<TOut>(
		iter: Iterator<TOut, void, void> | AsyncIterator<TOut, void, void>
		): AutoPromise<TOut[]> {

	let lItems: TOut[] = []
	while(true) {
		const {value, done} = await iter.next()
		if (done) {
			break
		}
		else {
			lItems.push(value)
		}
	}
	return lItems
}

