export const accumFrom = <TOut, TAccum>(
		iter: Iterator<TOut, TAccum>,
		initAcc: TAccum
		): TAccum => {

	let retval: TAccum = initAcc
	while(true) {
		const {value, done} = iter.next()
		if (done) {
			return retval
		}
	}
}

